from typing import Optional, Union
from .ah_report_configuration import AHReportConfiguration
from .ah_report_service import AHReportService
from .ah_report_builder import AHReportBuilder
from .models.reports import AHAlertType, AHAlertStatus, AHAlertLevel
from .models.results import AHLogResult, AHAlertResult, AHAdoptionResult, AHCommonResult
from .models.protocols import AHReportError


class AHReporter:
    _instance: Optional['AHReporter'] = None

    def __init__(self, configuration: Optional[AHReportConfiguration] = None,
                 service: Optional[AHReportService] = None):
        self.configuration = configuration or AHReportConfiguration()
        self.service = service or AHReportService()
        self.builder = AHReportBuilder(self.configuration)

    @classmethod
    def get_instance(cls) -> 'AHReporter':
        if cls._instance is None:
            cls._instance = cls()
        return cls._instance

    def send(self, report, result_type):
        if not self.configuration.get_is_report_code():
            return AHReportError.validation_failed('Reporting is disabled')
        return self.service.send(report, result_type)

    def send_post_to_route(self, route: str, data: dict):
        self.service.send_post_to_route(route, data)

    def report_log(self, message: str, sub_type: str,
                   user_defined: Optional[dict] = None) -> Union[AHLogResult, AHReportError]:
        username = self.configuration.get_username()
        if not username or not username.strip():
            return AHReportError.validation_failed('Username is required')
        report = self.builder.build_log_report(message, sub_type, user_defined)
        return self.send(report, AHLogResult)

    def report_alert(self, alert_type: str, status: str, title: str,
                     message: Optional[str] = None, level: Optional[str] = None,
                     service_name: Optional[str] = None, request_id: Optional[str] = None,
                     api_url: Optional[str] = None, response_time: Optional[float] = None,
                     error_code: Optional[str] = None,
                     ext_data: Optional[dict] = None) -> Union[AHAlertResult, AHReportError]:
        username = self.configuration.get_username()
        if not username or not username.strip():
            return AHReportError.validation_failed('Username is required')
        report = self.builder.build_alert_report(
            alert_type, status, title, message, level,
            service_name, request_id, api_url, response_time, error_code, ext_data
        )
        return self.send(report, AHAlertResult)

    def report_ide_mcp_call_error(self, title: str, message: Optional[str] = None,
                                  response_time: Optional[float] = None,
                                  error_code: Optional[str] = None,
                                  ext_data: Optional[dict] = None) -> Union[AHAlertResult, AHReportError]:
        return self.report_alert(
            AHAlertType.IDE_MCP_CALL, AHAlertStatus.FAILED, title,
            message=message, level=AHAlertLevel.ERROR,
            response_time=response_time, error_code=error_code, ext_data=ext_data
        )

    def report_mcp_service_error(self, title: str, message: Optional[str] = None,
                                 service_name: Optional[str] = None,
                                 error_code: Optional[str] = None,
                                 ext_data: Optional[dict] = None) -> Union[AHAlertResult, AHReportError]:
        return self.report_alert(
            AHAlertType.MCP_SERVICE, AHAlertStatus.ERROR, title,
            message=message, level=AHAlertLevel.CRITICAL,
            service_name=service_name, error_code=error_code, ext_data=ext_data
        )

    def report_api_request_error(self, title: str, message: Optional[str] = None,
                                 api_url: Optional[str] = None,
                                 response_time: Optional[float] = None,
                                 error_code: Optional[str] = None,
                                 ext_data: Optional[dict] = None) -> Union[AHAlertResult, AHReportError]:
        return self.report_alert(
            AHAlertType.API_REQUEST, AHAlertStatus.FAILED, title,
            message=message, level=AHAlertLevel.ERROR,
            api_url=api_url, response_time=response_time,
            error_code=error_code, ext_data=ext_data
        )

    def report_adoption(self, is_accepted: bool, accept_code: str, file_path: str,
                        repository_url: str, prompt_count: int, ask_type: int,
                        ext: Optional[dict] = None) -> Union[AHAdoptionResult, AHReportError]:
        username = self.configuration.get_username()
        if not username or not username.strip():
            return AHReportError.validation_failed('Username is required')
        report = self.builder.build_adoption_report(
            is_accepted, accept_code, file_path, repository_url, prompt_count, ask_type, ext
        )
        return self.send(report, AHAdoptionResult)

    def report_model_accessibility(self, model: str, source_type: Optional[str] = None,
                                   git_url: Optional[str] = None) -> Union[AHCommonResult, AHReportError]:
        username = self.configuration.get_username()
        if not username or not username.strip():
            return AHReportError.validation_failed('Username is required')
        report = self.builder.build_model_accessibility_report(username, model, source_type, git_url)
        return self.send(report, AHCommonResult)

    def report_model_record(self, model: str,
                            source_type: Optional[str] = None) -> Union[AHCommonResult, AHReportError]:
        username = self.configuration.get_username()
        if not username or not username.strip():
            return AHReportError.validation_failed('Username is required')
        report = self.builder.build_model_record_report(username, model, source_type)
        return self.send(report, AHCommonResult)

    def set_username(self, username: str):
        self.configuration.set_username(username)

    def set_is_report_code(self, value: bool):
        self.configuration.set_is_report_code(value)

    def set_app_version(self, app_version: str):
        self.configuration.set_app_version(app_version)

    def set_mcp_version(self, mcp_version: str):
        self.configuration.set_mcp_version(mcp_version)

    def set_ide_type(self, ide_type: int):
        self.configuration.set_ide_type(ide_type)

    def set_app_id(self, app_id: str):
        self.configuration.set_app_id(app_id)

    def get_username(self) -> str:
        return self.configuration.get_username()

    def get_app_version(self) -> str:
        return self.configuration.get_app_version()

    def get_mcp_version(self) -> str:
        return self.configuration.get_mcp_version()

    def get_ide_type(self) -> int:
        return self.configuration.get_ide_type()

    def get_app_id(self) -> str:
        return self.configuration.get_app_id()

    def get_user_agent(self) -> str:
        return self.configuration.get_user_agent()
